import os
import importlib.util

TARGET_CODE_PATH = os.environ['TARGET_CODE_PATH']
spec = importlib.util.spec_from_file_location('target_module', TARGET_CODE_PATH)
target = importlib.util.module_from_spec(spec)
spec.loader.exec_module(target)
sorted_intersection = target.sorted_intersection

def test_basic_intersection():
    assert sorted_intersection([1, 2, 3], [2, 3, 4]) == [2, 3]

def test_unsorted_input():
    assert sorted_intersection([3, 1, 2], [4, 2, 3]) == [2, 3]

def test_duplicates():
    assert sorted_intersection([1, 2, 2, 3], [2, 2, 3, 4]) == [2, 3]

def test_no_intersection():
    assert sorted_intersection([1, 2], [3, 4]) == []

def test_empty_lists():
    assert sorted_intersection([], []) == []
    assert sorted_intersection([1, 2], []) == []
    assert sorted_intersection([], [1, 2]) == []

def test_type_error_not_list():
    try:
        sorted_intersection("not a list", [1, 2])
        assert False, "Should have raised TypeError for left"
    except TypeError as e:
        assert str(e) == "left must be a list"

    try:
        sorted_intersection([1, 2], "not a list")
        assert False, "Should have raised TypeError for right"
    except TypeError as e:
        assert str(e) == "right must be a list"

def test_type_error_non_int():
    try:
        sorted_intersection([1, "2"], [2, 3])
        assert False, "Should have raised TypeError for non-int in left"
    except TypeError as e:
        assert str(e) == "values must be integers"

    try:
        sorted_intersection([1, 2], [2, "3"])
        assert False, "Should have raised TypeError for non-int in right"
    except TypeError as e:
        assert str(e) == "values must be integers"

